import type { NextRequest } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { z } from 'zod'

const querySchema = z.object({
  from: z.string().datetime({ offset: true }).optional(),
  to: z.string().datetime({ offset: true }).optional(),
  group_by: z.enum(['day', 'week', 'month']).default('day'),
})

export async function GET(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return new Response('Unauthorized', { status: 401 })
  if (!['owner', 'admin'].includes(auth.role)) return new Response('Forbidden', { status: 403 })

  const parsed = querySchema.safeParse(Object.fromEntries(req.nextUrl.searchParams))
  if (!parsed.success) return Response.json({ error: parsed.error.flatten() }, { status: 400 })

  const { from, to, group_by } = parsed.data
  const supabase = await createClient()

  try {
    let query = supabase
      .from('bookings')
      .select('id, status, scheduled_at, service_id, source, services(name)')
      .eq('studio_id', auth.studioId)
      .order('scheduled_at', { ascending: true })

    if (from) query = query.gte('scheduled_at', from)
    if (to) query = query.lte('scheduled_at', to)

    const { data: bookings, error } = await query
    if (error) throw error

    const total = bookings?.length ?? 0
    const completed = (bookings ?? []).filter((b) => b.status === 'completed').length
    const noShows = (bookings ?? []).filter((b) => b.status === 'no_show').length
    const cancelled = (bookings ?? []).filter((b) => b.status === 'cancelled').length

    // Timeline of bookings by period
    const grouped = (bookings ?? []).reduce<Record<string, number>>((acc, b) => {
      const d = new Date(b.scheduled_at)
      let key: string
      if (group_by === 'month') key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`
      else if (group_by === 'week') {
        const dow = d.getDay()
        const startOfWeek = new Date(d)
        startOfWeek.setDate(d.getDate() - dow)
        key = startOfWeek.toISOString().slice(0, 10)
      } else key = d.toISOString().slice(0, 10)
      acc[key] = (acc[key] ?? 0) + 1
      return acc
    }, {})

    const timeline = Object.entries(grouped)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([period, count]) => ({ period, count }))

    // Day of week × hour heatmap
    const heatmap: number[][] = Array.from({ length: 7 }, () => Array.from<number>({ length: 24 }).fill(0))
    for (const b of bookings ?? []) {
      const d = new Date(b.scheduled_at)
      const row = heatmap[d.getDay()]
      if (row) row[d.getHours()] = (row[d.getHours()] ?? 0) + 1
    }

    // Service popularity
    const serviceCounts = (bookings ?? []).reduce<Record<string, { name: string; count: number }>>((acc, b) => {
      if (!b.service_id) return acc
      const svc = b.services
      const name = Array.isArray(svc) ? (svc[0]?.name ?? b.service_id) : ((svc as { name?: string } | null)?.name ?? b.service_id)
      if (!acc[b.service_id]) acc[b.service_id] = { name, count: 0 }
      acc[b.service_id]!.count++
      return acc
    }, {})

    const serviceRanking = Object.values(serviceCounts).sort((a, b) => b.count - a.count)

    return Response.json({
      kpis: {
        total,
        completed,
        noShows,
        cancelled,
        noShowRate: total > 0 ? Math.round((noShows / total) * 100) : 0,
        cancellationRate: total > 0 ? Math.round((cancelled / total) * 100) : 0,
      },
      timeline,
      heatmap,
      serviceRanking,
    })
  } catch (err) {
    logger.error({ err, studioId: auth.studioId }, 'bookings report failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { Metadata } from 'next'
import { PageShell } from '@/components/shared/PageShell'
import { PageHeader } from '@/components/shared/PageHeader'
import { PageViews } from '@/components/shared/PageViews'
import { ReportsTabNav } from '@/components/reports/ReportsTabNav'

export const metadata: Metadata = { title: 'Reports — InkOS' }

export default function ReportsLayout({ children }: { children: React.ReactNode }) {
  return (
    <PageShell>
      <PageHeader title="Reports" description="Studio analytics and performance insights" />
      <PageViews>
        <ReportsTabNav />
      </PageViews>
      {children}
    </PageShell>
  )
}

'use client'

import { useQuery } from '@tanstack/react-query'
import { CalendarDays, TrendingDown } from 'lucide-react'
import { KpiCard } from '@/components/shared/KpiCard'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Skeleton } from '@/components/ui/skeleton'
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { ChartSkeleton } from '@/components/skeletons'
import dynamic from 'next/dynamic'

const RechartsBarChart = dynamic(() => import('./RechartsBarChart'), {
  ssr: false,
  loading: () => <Skeleton className="h-56 w-full" />,
})

interface BookingKpis {
  total: number
  completed: number
  noShows: number
  cancelled: number
  noShowRate: number
  cancellationRate: number
}

interface BookingsData {
  kpis: BookingKpis
  timeline: Array<{ period: string; count: number }>
  heatmap: number[][] // [7][24]
  serviceRanking: Array<{ name: string; count: number }>
}

const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']

function HeatmapCell({ value, max }: { value: number; max: number }) {
  const intensity = max > 0 ? value / max : 0
  const opacity = Math.round(intensity * 100)
  return (
    <div
      title={`${value} bookings`}
      className="h-3 w-3 rounded-sm"
      style={{ backgroundColor: `hsl(var(--color-primary) / ${Math.max(opacity, 4)}%)` }}
    />
  )
}

export function BookingsReportClient() {
  const { data, isLoading, error } = useQuery<BookingsData>({
    queryKey: ['reports', 'bookings'],
    queryFn: () => fetch('/api/reports/bookings').then((r) => r.json()),
    staleTime: 5 * 60 * 1000,
  })

  return (
    <DataState
      data={data}
      isLoading={isLoading}
      isError={!!error}
      error={error instanceof Error ? error : null}
      loadingSlot={<ChartSkeleton />}
      emptySlot={
        <EmptyState
          icon={CalendarDays}
          title="No booking data yet"
          description="Bookings will appear here once your first appointment is completed."
          variant="default"
        />
      }
    >
      {(d) => {
        const timelineForChart = d.timeline.map((r) => ({ name: r.period, value: r.count }))
        const maxHeat = Math.max(...d.heatmap.flat())

        return (
          <div className="space-y-6">
            {/* KPIs */}
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
              <KpiCard label="Total Bookings" value={d.kpis.total} subtextLabel="in period" icon={CalendarDays} index={0} />
              <KpiCard label="Completed" value={d.kpis.completed} subtextLabel="sessions completed" icon={CalendarDays} trend="up" index={1} />
              <KpiCard label="No-Shows" value={d.kpis.noShows} subtextLabel={`${d.kpis.noShowRate}% no-show rate`} icon={TrendingDown} invertTrend trend={d.kpis.noShows > 0 ? 'up' : 'neutral'} index={2} />
              <KpiCard label="Cancelled" value={d.kpis.cancelled} subtextLabel={`${d.kpis.cancellationRate}% cancellation rate`} icon={TrendingDown} invertTrend trend={d.kpis.cancelled > 0 ? 'up' : 'neutral'} index={3} />
              <KpiCard label="No-Show Rate" value={`${d.kpis.noShowRate}%`} subtextLabel="of total bookings" icon={TrendingDown} invertTrend trend={d.kpis.noShowRate > 10 ? 'up' : 'neutral'} index={4} />
              <KpiCard label="Cancellation Rate" value={`${d.kpis.cancellationRate}%`} subtextLabel="of total bookings" icon={TrendingDown} invertTrend trend={d.kpis.cancellationRate > 15 ? 'up' : 'neutral'} index={5} />
            </div>

            {/* Bookings timeline */}
            <Card className="border-border/50 shadow-[var(--shadow-card)]">
              <CardHeader>
                <CardTitle className="text-sm font-medium">Bookings Over Time</CardTitle>
              </CardHeader>
              <CardContent>
                {timelineForChart.length === 0 ? (
                  <EmptyState icon={CalendarDays} title="No booking data yet" description="Bookings will appear here once created." />
                ) : (
                  <RechartsBarChart
                    data={timelineForChart}
                    dataKey="value"
                    label="Bookings"
                    formatValue={(v) => `${v}`}
                  />
                )}
              </CardContent>
            </Card>

            {/* Heatmap */}
            <Card className="border-border/50 shadow-[var(--shadow-card)]">
              <CardHeader>
                <CardTitle className="text-sm font-medium">Booking Heatmap — Day × Hour</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="overflow-x-auto">
                  <div className="inline-flex flex-col gap-1 min-w-max">
                    <div className="flex gap-1 pl-8">
                      {Array.from({ length: 24 }, (_, h) => (
                        <div key={h} className="w-3 text-center text-[9px] text-muted-foreground leading-none">
                          {h % 6 === 0 ? `${h}` : ''}
                        </div>
                      ))}
                    </div>
                    {d.heatmap.map((row, dayIndex) => (
                      <div key={dayIndex} className="flex items-center gap-1">
                        <span className="w-7 text-right text-[10px] text-muted-foreground shrink-0">
                          {DAYS[dayIndex]}
                        </span>
                        {row.map((val, h) => (
                          <HeatmapCell key={h} value={val} max={maxHeat} />
                        ))}
                      </div>
                    ))}
                  </div>
                </div>
                <p className="mt-3 text-xs text-muted-foreground">Darker = more bookings at that day/hour.</p>
              </CardContent>
            </Card>

            {/* Service ranking */}
            {d.serviceRanking.length > 0 && (
              <Card className="border-border/50 shadow-[var(--shadow-card)]">
                <CardHeader>
                  <CardTitle className="text-sm font-medium">Services by Popularity</CardTitle>
                </CardHeader>
                <CardContent className="p-0">
                  <div className="divide-y divide-border/50">
                    {d.serviceRanking.slice(0, 10).map((svc, i) => (
                      <div key={svc.name} className="flex items-center gap-4 px-6 py-3">
                        <span className="w-5 text-center text-sm font-bold text-muted-foreground tabular-nums">{i + 1}</span>
                        <span className="flex-1 text-sm font-medium truncate">{svc.name}</span>
                        <Badge variant="secondary">{svc.count} bookings</Badge>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        )
      }}
    </DataState>
  )
}
